import React, { useState, useCallback, useEffect } from 'react'
import { View, Text, TouchableOpacity, Dimensions, FlatList } from 'react-native'

import { useContexState } from '../../hooks/context';
import { styles } from './styles';

export function ShoppingCart() {
    const {
        shoppingCartItem,
        setShoppingCartItem,
        selectedNumber,
        setSelectedNumber,
        shoppingCartActive,
        setShoppingCartActive,

    } = useContexState();

    //const numberValue = [122, 3785, 9873, 3122, 45, 453, 3455, 776, 2235, 2343, 56, 358, 109, 122, 3785, 9873, 3122, 45, 453, 3455, 776, 2235, 2343, 56, 358, 109]


    let result = [] as { id: number, number: number }[]

    for (let i = 0; i < shoppingCartItem.length; i++) {
        result.push({ id: i, number: shoppingCartItem[i] })
    };

    /*
        let result = shoppingCartItem.map((item, index) => {
            return { id: index, number: shoppingCartItem[index] }
        })
    */

    const keyExtractor = useCallback(
        (item) => item.id.toString(), []
    );
    /*
        function deleteItem() {
            const estados = ["RJ", "MG", "SP", "SC", "SP", "SP", "PR", "PE", "PA"];
            const buscar = "RJ";
            let indice = estados.indexOf(buscar);
            while (indice >= 0) {
                estados.splice(indice, 1);
                indice = estados.indexOf(buscar);
            }
            console.log(estados);
        }
    */





    const testResult = [{ id: 0, number: 32435 }, { id: 1, number: 596 }, { id: 2, number: 2455 }]

    const handleRemoveItem = (i: number) => {
        const temp = [...shoppingCartItem];
        const buscar = i;
        let indice = temp.indexOf(buscar);
        while (indice >= 0) {
            temp.splice(indice, 1);
            indice = temp.indexOf(buscar);
        }
        setShoppingCartItem(temp)
    }


    interface CardType {
        value: {
            id: number;
            number: number;
        }
    }




    const [numberSelectDelete, setNumberSelectDelete] = useState<number[]>([])

    function Card({ value }: CardType) {

        const temp = [...numberSelectDelete];
        const buscar = value.number;
        let indice = temp.indexOf(buscar);

        function SelectDelete() {
            if (numberSelectDelete[indice]) {
                while (indice >= 0) {
                    temp.splice(indice, 1);
                    indice = temp.indexOf(buscar);
                }
                setNumberSelectDelete(temp)
            } else {
                setNumberSelectDelete([...temp, value.number])
            }
        }

        return <TouchableOpacity style={{ alignItems: 'flex-end' }} onPress={() => SelectDelete()}>
            <Text style={[styles.listText, numberSelectDelete[indice] ? { backgroundColor: '#FF0000', color: '#fff' } : null]}>
                {(`0000${value.number}`).slice(-4)}
            </Text>
        </TouchableOpacity>
    }


    const conta = (shoppingCartItem.length - numberSelectDelete.length) * 19.99;
    const arredondado = parseFloat(conta.toFixed(2));
    const price = arredondado.toString().replace('.', ',');

    return (shoppingCartActive ? <>
        <TouchableOpacity onPress={() => {
            setShoppingCartActive(false)
        }} style={{
            position: 'absolute',
            alignItems: 'center',
            justifyContent: 'center',
            minWidth: Dimensions.get('window').width,
            minHeight: Dimensions.get('window').height
        }} />

        <View style={styles.container} >
            <Text style={{ color: '#fff', fontSize: 20, textAlign: 'center', marginVertical: 6 }}>{`${shoppingCartItem.length - numberSelectDelete.length} POR APENAS${"\n"}R$ ${price}`}</Text>
            <FlatList
                data={result /*result*/}
                keyExtractor={keyExtractor}
                numColumns={4}
                renderItem={({ item }) => <Card value={item} />}
            />

            <TouchableOpacity style={[styles.buttonPay, numberSelectDelete.length > 0 ? { backgroundColor: '#FF0000' } : null]} >
                <Text style={styles.payText}>{numberSelectDelete.length > 0 ? 'Excluir' : 'Pagar'}</Text>
            </TouchableOpacity>
        </View>
    </> : null
    );
};

